def count_sequences(n, threshold):
    count = 0
    for d1 in range(1, n):
        for d2 in range(1, n):
            if d1 + d2 >= n: break
            for d3 in range(1, n):
                if d1 + d2 + d3 >= n: break
                for d4 in range(1, n):
                    if d1 + d2 + d3 + d4 >= n: break
                    d5 = n - (d1 + d2 + d3 + d4)
                    if d5 >= 1:
                        s = [d1+d2, d2+d3, d3+d4, d4+d5, d5+d1]
                        acute_count = sum(1 for x in s if x >= threshold)
                        if acute_count == 2:
                            count += 1
    return count

