def solve_small(n):
    total_pentagons = 0
    for combo in itertools.combinations(range(n), 5):
        if count_acute_angles(combo, n) == 2:
            total_pentagons += 1
    return total_pentagons

import itertools

def count_acute_angles(pentagon_indices, n):
    p = list(pentagon_indices)
    d = []
    for i in range(4):
        d.append(p[i+1] - p[i])
    d.append(n + p[0] - p[4])
    s = []
    for i in range(5):
        s.append(d[i] + d[(i+1)%5])
    acute_count = 0
    for i in range(5):
        if s[i] > n/2:
            acute_count += 1
    return acute_count

